INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51111, 'Judges 6:12', 'Judges', 6, 12, 'په هغه ځای کې د څښتن فرښته جدعون ته ښکاره شوه او ویې ویل: «ای زړور او قوي سړیه، څښتن ستا سره مل دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_12.mp3', '', 1761754199, 1761754199),
(51112, 'Judges 6:13', 'Judges', 6, 13, 'جدعون په ځواب کې وویل: «خو ښاغلیه، که چېرې څښتن زمونږ سره مل وي، نو دا هرڅه ولې زمونږ سره وشول؟ څه شوې د هغه حیرانوونکې معجزې د کومو په هکله چې به زمونږ پلرونو مونږ ته کیسې کولې او داسې به یې ویل چې څښتن څنګه مونږ د مصر څخه راوویستلو؟ خو اوس یې مونږ پریښي یو او مدیانیانو ته یې په لاس ورکړي یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_13.mp3', '', 1761754199, 1761754199),
(51113, 'Judges 6:14', 'Judges', 6, 14, 'بیا څښتن هغه ته مخ ورواړاوه او ویې ویل: «په خپل ټول قوت سره چې لرې یې، لاړ شه او اسراییلیان د مدیانیانو څخه وژغوره. زه په خپله تا لېږم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_14.mp3', '', 1761754199, 1761754199),
(51114, 'Judges 6:15', 'Judges', 6, 15, 'جدعون په ځواب کې وویل: «خو څښتنه، زه څنګه کولای شم چې اسراییلیان وژغورم؟ د منسي په قبیله کې زما کورنۍ د ټولو څخه کمزورې ده او زه په خپله کورنۍ کې د ټولو څخه وړوکی کس یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_15.mp3', '', 1761754199, 1761754199),
(51115, 'Judges 6:16', 'Judges', 6, 16, 'څښتن په ځواب کې وویل: «ته دا کار کولای شې، ځکه چې زه به ستا سره مرسته وکړم. ته به مدیانیانو ته داسې په اسانۍ سره ماتې ورکړې لکه د یو کس سره چې جنګ کوې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_16.mp3', '', 1761754199, 1761754199),
(51116, 'Judges 6:17', 'Judges', 6, 17, 'جدعون وویل: «که چېرې ته په رښتیا غواړې چې زما سره مرسته وکړې، نو ماته یوه نښه وښایه چې دا ثابته کړي چې په رښتیا څښتن زما سره خبرې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_17.mp3', '', 1761754199, 1761754199),
(51117, 'Judges 6:18', 'Judges', 6, 18, 'مهرباني وکړه زما د راتګه پورې همدلته اوسه چې زه خپله نذرانه راوړم او ستا په حضور کې یې کېږدم.» څښتن وویل: «زه به ستا د بېرته راتګ پورې دلته پاتې شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_18.mp3', '', 1761754199, 1761754199),
(51118, 'Judges 6:19', 'Judges', 6, 19, 'جدعون کور ته ننوت او یو سېرلی یې حلال کړ. د هغه غوښه یې پخه کړه، لس کیلو ګرامه اوړه یې راواخیستل او فطیره ډوډۍ یې ورڅخه پخه کړه. بیا هغه غوښه په یوه ټوکرۍ کې واچوله، د هغې ښوروا یې هم په یوه کاسه کې واچوله، د څښتن فرښتې ته یې چې د څېړۍ د ونې لاندې ناسته وه راوړه او د هغې په مخکې یې کېښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_19.mp3', '', 1761754199, 1761754199),
(51119, 'Judges 6:20', 'Judges', 6, 20, 'فرښتې هغه ته وویل: «دا غوښه او ډوډۍ راواخله او په دې ګټ باندې یې کېږده او ښوروا ورباندې توی کړه.» نو جدعون همداسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_20.mp3', '', 1761754199, 1761754199),
(51120, 'Judges 6:21', 'Judges', 6, 21, 'د څښتن فرښتې د امسا په څوکې باندې چې په لاس کې یې وه غوښه او ډوډۍ لمس کړه. د ګټ څخه د اور لمبه پورته شوه او غوښه او ډوډۍ یې وسوځوله. وروسته بیا فرښته پناه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_21.mp3', '', 1761754199, 1761754199),
(51121, 'Judges 6:22', 'Judges', 6, 22, 'کله چې جدعون پوه شو چې دا د څښتن فرښته وه، هغه د وېرې وویل: «ای څښتن تعالی! ما ستا فرښته مخامخ ولیدله.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_22.mp3', '', 1761754199, 1761754199),
(51122, 'Judges 6:23', 'Judges', 6, 23, 'خو څښتن هغه ته وویل: «ارام شه. مه وېرېږه. ته به نه مړ کېږې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_23.mp3', '', 1761754199, 1761754199),
(51123, 'Judges 6:24', 'Judges', 6, 24, 'جدعون د څښتن دپاره د قربانۍ ځای جوړ کړ او دا نوم یې ورباندې کېښود چې «څښتن د سولې او سلامتۍ سرچینه ده.» او تر اوسه پورې هغه د ابیعزریانو د عفره په کلي کې پاتې دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_24.mp3', '', 1761754199, 1761754199),
(51124, 'Judges 6:25', 'Judges', 6, 25, 'په هماغه شپه څښتن جدعون ته وویل: «د خپل پلار د پادې څخه دې یو غویی چې اووه کلن وي بوځه او د خپل پلار د قربانۍ ځای چې د بعل دپاره دی، وران کړه او د اشیره بت چې د هغه په څنګ کې دی راوغورځوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_25.mp3', '', 1761754199, 1761754199),
(51125, 'Judges 6:26', 'Judges', 6, 26, 'بیا خپل څښتن خدای ته ستاسو د کلي د غونډۍ په ډېر لوړ ځای باندې د قربانۍ یو مناسب ځای جوړ کړه. د اور دپاره د اشیره د بت د لرګیو څخه کار واخله او هغه غویی حلال کړه او د سوځېدونکې نذرانې په توګه یې وړاندې کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_26.mp3', '', 1761754199, 1761754199),
(51126, 'Judges 6:27', 'Judges', 6, 27, 'نو جدعون د خپلو نوکرانو څخه لس کسان د ځان سره بوتلل او د څښتن په خبره باندې یې عمل وکړ. نو څرنګه چې هغه د خپلې کورنۍ او د کلي د نورو خلکو څخه وېرېده چې د ورځې له خوا دا کار وکړي، نو هغه کار یې د شپې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_27.mp3', '', 1761754199, 1761754199),
(51127, 'Judges 6:28', 'Judges', 6, 28, 'کله چې سبا سهار وختي د کلي خلک پاڅېدل، هغوی ولیدل چې د بعل د قربانۍ ځای وران شوی ؤ او د اشیره بت چې د هغه په څنګ کې ؤ، راغورځېدلی ؤ او غویی د قربانۍ په نوي ځای کې قرباني شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_28.mp3', '', 1761754199, 1761754199),
(51128, 'Judges 6:29', 'Judges', 6, 29, 'هغوی د یو بل څخه پوښتنه وکړه: «دا کار چا کړی دی؟» کله چې هغوی د دې خبرې څېړنه وکړه، نو معلومه شوه چې جدعون د یوآش زوی دا کار کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_29.mp3', '', 1761754199, 1761754199),
(51129, 'Judges 6:30', 'Judges', 6, 30, 'نو د کلي خلکو یوآش ته وویل: «خپل زوی راوباسه. هغه باید ووژل شي، ځکه چې هغه د بعل د قربانۍ ځای وران کړی دی او د اشیره بت چې د هغه په څنګ کې ؤ، هغه یې راغورځولی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_30.mp3', '', 1761754199, 1761754199),
(51130, 'Judges 6:31', 'Judges', 6, 31, 'خو یوآش هغو ټولو خلکو ته چې د هغه مخالف وو وویل: «ایا تاسو د بعل دپاره دا بحث کوئ؟ ایا تاسو د هغه څخه دفاع کوئ؟ هرڅوک چې د هغه دپاره جګړه کوي، هغه به تر سبا سهاره پورې وژل کیږي. که چېرې هغه خدای وي پرېږدئ چې هغه د خپل ځان ساتنه وکړي، دا د هغه د قربانۍ ځای دی چې وران شوی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_31.mp3', '', 1761754199, 1761754199),
(51131, 'Judges 6:32', 'Judges', 6, 32, 'له هغه وخت څخه راهیسې جدعون د یربعل په نوم مشهور شو، ځکه چې یوآش وویل: «پرېږدئ چې بعل د خپل ځان څخه دفاع وکړي، ځکه چې دا د هغه د قربانۍ ځای دی چې وران شوی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_32.mp3', '', 1761754199, 1761754199),
(51132, 'Judges 6:33', 'Judges', 6, 33, 'بیا ټول مدیانیان، عمالیقیان او د دښتې د قبیلو خلک سره راټول شول، هغوی د اردن د سیند څخه تېر شول او د یزرعیل په دره کې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_33.mp3', '', 1761754199, 1761754199),
(51133, 'Judges 6:34', 'Judges', 6, 34, 'په جدعون باندې د څښتن روح نازل شو او هغه سرنی وواهه او د ابیعزر د طایفې خلک یې راوغوښتل او هغوی د جدعون پسې روان شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_34.mp3', '', 1761754199, 1761754199),
(51134, 'Judges 6:35', 'Judges', 6, 35, 'جدعون د منسي ټولې سیمې ته استازي ولېږل چې راشي او د هغه سره یوځای شي. همدارنګه هغه د اشیر، زبولون او نفتالي قبیلو ته هم استازي ولېږل او هغوی راغلل او د جدعون سره یوځای شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_35.mp3', '', 1761754199, 1761754199),
(51135, 'Judges 6:36', 'Judges', 6, 36, 'بیا جدعون خدای ته وویل: «لکه څنګه چې تا وعده کړې ده چې اسراییلیان به زما په لاس وژغورې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_36.mp3', '', 1761754199, 1761754199),
(51136, 'Judges 6:37', 'Judges', 6, 37, 'ښه ده، زه به د پسه وړۍ په درمند باندې کېږدم. که چېرې سهار یوازې په وړیو باندې پرخه پرته وي او ځمکه وچه وي، بیا به زه پوه شم چې ته به اسراییلیان زما په لاس وژغورې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_37.mp3', '', 1761754199, 1761754199),
(51137, 'Judges 6:38', 'Judges', 6, 38, 'او کټ مټ همداسې وشول. کله چې جدعون بله ورځ سهار وختي پاڅېده، هغه لاړ او د پسه وړۍ یې په کاسه کې وزبېښلې او کاسه د اوبو څخه ډکه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_38.mp3', '', 1761754199, 1761754199),
(51138, 'Judges 6:39', 'Judges', 6, 39, 'بیا جدعون خدای ته وویل: «په ما باندې په قهر نه شې. اجازه راکړه چې یوه بله غوښتنه وکړم چې یوځل بیا په وړیو باندې ازمېښت وکړم. دا ځل دې وړۍ وچې پاتې شي او ځمکه دې په پرخې باندې لمده شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_39.mp3', '', 1761754199, 1761754199),
(51139, 'Judges 6:40', 'Judges', 6, 40, 'په هغه شپه خدای همداسې وکړل. سهار یوازې وړۍ وچې وې، خو ځمکه په پرخې باندې لمده وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges6_verse_40.mp3', '', 1761754199, 1761754199),
(51140, 'Numbers 32:1', 'Numbers', 32, 1, 'د روبین او جاد قبیلو ډېرې پادې او رمې درلودلې او هغوی ولیدل چې د یعزیر او جلعاد سیمې ډېر ښه څړځایونه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_1.mp3', '', 1761754199, 1761754199),
(51141, 'Numbers 32:2', 'Numbers', 32, 2, 'نو هغوی موسی، العازار او د اسراییلو نورو مشرانو ته ورغلل او ورته ویې ویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_2.mp3', '', 1761754199, 1761754199),
(51142, 'Numbers 32:5', 'Numbers', 32, 5, 'مهرباني وکړئ دغه ځمکه مونږ ته د خپل جایداد په توګه راکړئ او مونږ دې ته مه مجبوروئ چې د اردن د سیند څخه تېر شو او هلته واوسېږو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_5.mp3', '', 1761754199, 1761754199),
(51143, 'Numbers 32:6', 'Numbers', 32, 6, 'موسی په ځواب کې وویل: «نور اسراییلیان به جنګ ته ځي او تاسو غواړئ چې دلته پاتې شئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_6.mp3', '', 1761754199, 1761754199),
(51144, 'Numbers 32:7', 'Numbers', 32, 7, 'تاسو ولې د اسراییلیانو زړونه هغه وطن ته د ورتللو څخه توروئ چې څښتن هغوی ته ورکړی دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_7.mp3', '', 1761754199, 1761754199),
(51145, 'Numbers 32:8', 'Numbers', 32, 8, 'ستاسو پلرونو همداسې کار وکړ، کله چې ما هغوی د قادش برنیع څخه ولېږل چې هغه وطن وګوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_8.mp3', '', 1761754199, 1761754199),
(51146, 'Numbers 32:9', 'Numbers', 32, 9, 'هغوی د اشکول تر درې پورې لاړل او هغه وطن یې وکتلو، خو کله چې بېرته راستانه شول نو د خلکو زړونه یې هغه وطن ته د ورتګ څخه تور کړل چې څښتن هغوی ته ورکړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_9.mp3', '', 1761754199, 1761754199),
(51147, 'Numbers 32:10', 'Numbers', 32, 10, 'څښتن په هغه ورځ په قهر شو او داسې وعده یې وکړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_10.mp3', '', 1761754199, 1761754199),
(51148, 'Numbers 32:11', 'Numbers', 32, 11, 'په دې سبب چې هغوی د زړه له کومي زما څخه پیروي ونه کړه، نو زه قسم خورم چې د هغو کسانو څخه چې د مصر څخه راوتلي دي او عمرونه یې شل کاله یا زیات دي، هېڅوک هم نه شي کولای هغې خاورې ته ورننوځي چې ما د ابراهیم، اسحاق او یعقوب سره د هغې وعده کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_11.mp3', '', 1761754199, 1761754199),
(51149, 'Numbers 32:12', 'Numbers', 32, 12, 'په دوی کې پرته د یفنه قنزي د زوی کالیب او د نون د زوی یوشع څخه چې د زړه له کومي یې د څښتن پیروي وکړه، نور ټول شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_12.mp3', '', 1761754199, 1761754199),
(51150, 'Numbers 32:13', 'Numbers', 32, 13, 'څښتن په قوم باندې په قهر شو او هغوی یې مجبور کړل چې څلوېښت کاله په دښته کې سرګردانه وګرځي، تر هغې چې هغه ټول نسل چې د هغه په وړاندې یې ګناه کړې وه، مړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_13.mp3', '', 1761754199, 1761754199),
(51151, 'Numbers 32:14', 'Numbers', 32, 14, 'نو اوس تاسو د خپلو پلرونو ځای نیولی دی، یعنې د ګناهکارو خلکو یو نوی نسل چې دې ته تیار یئ چې یوځل بیا د اسراییلو په قوم باندې د څښتن غضب راولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_14.mp3', '', 1761754199, 1761754199),
(51152, 'Numbers 32:15', 'Numbers', 32, 15, 'اوس که چېرې تاسو د څښتن د پیروۍ څخه انکار وکړئ، هغه به یوځل بیا دا ټول خلک په دښته کې پرېږدي او د هغوی د بربادۍ مسوولیت به ستاسو په غاړه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_15.mp3', '', 1761754199, 1761754199),
(51153, 'Numbers 32:16', 'Numbers', 32, 16, 'د روبین او جاد خلکو په ځواب کې وویل: «مونږ پرېږدئ چې د خپلو رمو دپاره ځایونه او د خپلو ښځو او اولادونو دپاره ښارونه جوړ کړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_16.mp3', '', 1761754199, 1761754199),
(51154, 'Numbers 32:17', 'Numbers', 32, 17, 'بیا به مونږ دې ته تیار شو چې خپل ځانونه په وسلو باندې سمبال کړو او د نورو اسراییلیانو په مخکې به ځو، ترڅو هغوی خپل ځای ته ورولو. زمونږ ښځې او ماشومان به د هغې خاورې د اوسېدونکو څخه په دېوال لرونکو ښارونو کې خوندي اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_17.mp3', '', 1761754199, 1761754199),
(51155, 'Numbers 32:18', 'Numbers', 32, 18, 'مونږ به تر هغه وخته پورې خپلو کورونو ته ستانه نه شو، ترڅو نورو ټولو اسراییلیانو د خپلې ټاکل شوې ځمکې ملکیت تر لاسه کړی نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_18.mp3', '', 1761754199, 1761754199),
(51156, 'Numbers 32:19', 'Numbers', 32, 19, 'مونږ به د اردن د سیند په بله غاړه باندې د هغوی په منځ کې کومه ځمکه وانخلو، ځکه چې زمونږ برخه دلته د اردن په ختیځ کې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_19.mp3', '', 1761754199, 1761754199),
(51157, 'Numbers 32:20', 'Numbers', 32, 20, 'موسی په ځواب کې وویل: «که چېرې تاسو په رښتیا سره دا کار کوئ، نو همدلته د څښتن په حضور کې دې ته تیار شئ چې جنګ ته لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_20.mp3', '', 1761754199, 1761754199),
(51158, 'Numbers 32:21', 'Numbers', 32, 21, 'ستاسو ټول جنګي کسان دې د اردن د سیند څخه تېر شي او د څښتن په امر دې تر هغې پورې زمونږ په دښمنانو باندې خپلې حملې ته دوام ورکړي، ترڅو څښتن هغوی ته ماتې ورکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_21.mp3', '', 1761754199, 1761754199),
(51159, 'Numbers 32:22', 'Numbers', 32, 22, 'او د اسراییلیانو سره مرسته وکړي چې د هغې خاورې ملکیت تر لاسه کړي. له هغې څخه وروسته تاسو کولای شئ چې خپل وطن ته ستانه شئ، ځکه چې تاسو به خپل تعهد د څښتن او نورو اسراییلیانو په وړاندې سرته رسولی وي. بیا به څښتن دا ومني چې د اردن د ختیځې خوا دا ځمکه به ستاسو وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_22.mp3', '', 1761754199, 1761754199),
(51160, 'Numbers 32:23', 'Numbers', 32, 23, 'خو که چېرې تاسو په خپلې وعدې باندې ونه درېږئ، نو زه تاسو ته دا خبرداری درکوم چې تاسو به د څښتن په وړاندې ګناهکار اوسئ او د خپلې ګناه سزا به درکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_23.mp3', '', 1761754199, 1761754199),
(51161, 'Numbers 32:24', 'Numbers', 32, 24, 'نو د خپلو ښځو او اولادونو دپاره ښارونه او د خپلو رمو دپاره ځایونه جوړ کړئ. خو کومه وعده چې تاسو کړې ده، هغه سرته ورسوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_24.mp3', '', 1761754199, 1761754199),
(51162, 'Numbers 32:25', 'Numbers', 32, 25, 'د روبین او جاد خلکو وویل: «باداره، څه چې تاسو حکم کوئ، مونږ به هماغسې وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_25.mp3', '', 1761754199, 1761754199),
(51163, 'Numbers 32:26', 'Numbers', 32, 26, 'زمونږ ښځې او اولادونه، رمې او پادې به دلته د جلعاد په ښارونو کې پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_26.mp3', '', 1761754199, 1761754199),
(51164, 'Numbers 32:27', 'Numbers', 32, 27, 'خو زمونږ هغه کسان چې جګړې ته تیار دي، هغوی به د اردن د سیند څخه تېر شي او د څښتن په امر به وجنګیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_27.mp3', '', 1761754199, 1761754199),
(51165, 'Numbers 32:28', 'Numbers', 32, 28, 'نو موسی العازار، یوشع او د اسراییلو نورو مشرانو ته دا حکمونه ورکړل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_28.mp3', '', 1761754199, 1761754199),
(51166, 'Numbers 32:29', 'Numbers', 32, 29, '«که چېرې د روبین او جاد خلک د اردن څخه تېر شي او د څښتن په امر جګړې ته تیار شي او د هغوی په مرسته وکولای شئ چې هغه خاوره ونیسئ، نو بیا د جلعاد سیمه هغوی ته د هغوی د ملکیت په توګه ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_29.mp3', '', 1761754199, 1761754199),
(51167, 'Numbers 32:30', 'Numbers', 32, 30, 'خو که چېرې هغوی د اردن د سیند څخه تېر نه شي او ستاسو سره جګړې ته لاړ نه شي، نو دوی به په کنعان کې ستاسو سره خپل ملکیت واخلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_30.mp3', '', 1761754199, 1761754199),
(51168, 'Numbers 32:31', 'Numbers', 32, 31, 'د جاد او د روبین خلکو په ځواب کې وویل: «څنګه چې څښتن حکم کړی دی هماغسې به وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_31.mp3', '', 1761754199, 1761754199),
(51169, 'Numbers 32:32', 'Numbers', 32, 32, 'مونږ به د هغه تر قوماندې لاندې د کنعان خاورې ته ورننوت او جګړې ته به لاړ شو، ترڅو همدلته د اردن په ختیځ کې خپل ملکیت وساتو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_32.mp3', '', 1761754199, 1761754199),
(51170, 'Numbers 32:33', 'Numbers', 32, 33, 'نو موسی د جاد او روبین قبیلو او د یوسف د زوی منسي نیمې قبیلې ته د اموریانو د پاچا سیحون او د باشان د پاچا عوج ټوله سیمه ورکړه، چې په هغو کې ښارونه او د هغو شاوخوا سیمه هم شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_33.mp3', '', 1761754199, 1761754199),
(51171, 'Numbers 32:34', 'Numbers', 32, 34, 'د جاد قبیلې د دیبون، عطاروت، عروعیر،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_34.mp3', '', 1761754199, 1761754199),
(51172, 'Numbers 32:35', 'Numbers', 32, 35, 'عطروت شوفان، یعزیر، یجبهه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_35.mp3', '', 1761754199, 1761754199),
(51173, 'Numbers 32:36', 'Numbers', 32, 36, 'بیت نمره او د بیت هاران ښارونه بیا ودان کړل. د هغو ګرد چاپېره یې دېوالونه جوړ کړل او د خپلو رمو د ساتلو دپاره یې ځایونه هم جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_36.mp3', '', 1761754199, 1761754199),
(51174, 'Numbers 32:37', 'Numbers', 32, 37, 'د روبین قبیلې د حشبون، العاله، قریتایم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_37.mp3', '', 1761754199, 1761754199),
(51175, 'Numbers 32:38', 'Numbers', 32, 38, 'سبمه او هغه ښارونه چې د نبو او بعل معون په نوم پېژندل کېدل، بیا ودان کړل. دوی په هغو ټولو ښارونو باندې نوي نومونه کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_38.mp3', '', 1761754199, 1761754199),
(51176, 'Numbers 32:39', 'Numbers', 32, 39, 'د منسي د زوی ماخیر طایفې د جلعاد په خاوره باندې حمله وکړه او هغه یې ونیوله او اموریان یې د هغه ځای نه وشړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_39.mp3', '', 1761754199, 1761754199),
(51177, 'Numbers 32:40', 'Numbers', 32, 40, 'نو موسی د جلعاد سیمه د ماخیر طایفې ته ورکړه او هغوی په کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_40.mp3', '', 1761754199, 1761754199),
(51178, 'Numbers 32:41', 'Numbers', 32, 41, 'یاییر چې د منسي د قبیلې څخه ؤ، حمله وکړه او څو کلي یې ونیول او په هغو باندې یې دا نوم کېښود «د یاییر کلي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_41.mp3', '', 1761754199, 1761754199),
(51179, 'Numbers 32:42', 'Numbers', 32, 42, 'نوبح د قنات ښار د هغه د کلیو سره ونیوه او هغه یې د خپل ځان یعنې نوبح په نوم یاد کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers32_verse_42.mp3', '', 1761754199, 1761754199),
(51180, 'Joshua 18:1', 'Joshua', 18, 1, 'کله چې هغوی هغه خاوره ونیوله، د اسراییلو ټول قوم په شیلوه کې سره راټول شو او هلته یې سپېڅلې خېمه ودروله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_1.mp3', '', 1761754199, 1761754199),
(51181, 'Joshua 18:2', 'Joshua', 18, 2, 'خو د اسراییلو اووه قبیلې وې چې خپله د ځمکې برخه لا ورته نه وه ورکړل شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_2.mp3', '', 1761754199, 1761754199),
(51182, 'Joshua 18:3', 'Joshua', 18, 3, 'نو یوشع د اسراییلو قوم ته وویل: «تاسو به ترڅو پورې د هغې ځمکې په نیولو کې چې ستاسو د نیکونو څښتن خدای تاسو ته درکړې ده سستي کوئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_3.mp3', '', 1761754199, 1761754199),
(51183, 'Joshua 18:4', 'Joshua', 18, 4, 'د هرې قبیلې څخه درې درې تنه وټاکئ. زه به هغوی ولېږم چې ټول هېواد وګوري او هغه سیمه اندازه کړي چې هغوی به یې د خپل ملکیت په توګه تر لاسه کوي. بیا دې هغوی بېرته ماته راشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_4.mp3', '', 1761754199, 1761754199),
(51184, 'Joshua 18:5', 'Joshua', 18, 5, 'د هغوی په منځ کې به دا ځمکه په اوو برخو ووېشل شي. د یهودا قبیله به په خپله سیمه یعنې په جنوب کې پاتې شي او د یوسف اولاده به په خپله سیمه یعنې شمال کې پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_5.mp3', '', 1761754199, 1761754199),
(51185, 'Joshua 18:6', 'Joshua', 18, 6, 'وروسته له هغې چې تاسو د ځمکې د اوو برخو تشریح ولیکئ، ماته یې دلته راوړئ او زه به د خپل څښتن خدای په حضور کې ستاسو دپاره پچه واچوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_6.mp3', '', 1761754199, 1761754199),
(51186, 'Joshua 18:7', 'Joshua', 18, 7, 'خو بیاهم لاویان به ستاسو د پاتې خلکو سره د ځمکې برخه تر لاسه نه کړي، ځکه چې د هغوی برخه څښتن ته د کاهنانو په توګه خدمت کول دي. بې له شکه د جاد، روبین او د ختیځې منسي قبیلو لا مخکې د اردن د سیند په ختیځ کې خپله ځمکه تر لاسه کړې ده، هغه ځمکه د څښتن خدمتګار یعنې موسی هغوی ته ورکړې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_7.mp3', '', 1761754199, 1761754199),
(51187, 'Joshua 18:8', 'Joshua', 18, 8, 'څنګه چې هغه کسان د هغې ځمکې د نقشې اخیستلو دپاره روان شول، نو یوشع هغوی ته وویل: «لاړ شئ او د ټولې خاورې اندازه واخلئ او د هغه بیان ولیکئ. بیا ماته راشئ او زه به دلته په شیلوه کې د څښتن په حضور کې ستاسو دپاره پچه واچوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_8.mp3', '', 1761754199, 1761754199),
(51188, 'Joshua 18:9', 'Joshua', 18, 9, 'هغه کسان لاړل او په ټول هېواد کې وګرځېدل او دا یې ولیکل چې هغوی څنګه هغه ځمکه په اوو برخو ووېشله او د ښارګوټو لست یې جوړ کړ. بیا هغوی بېرته یوشع ته چې د شیلوه په کمپ کې ؤ راستانه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_9.mp3', '', 1761754199, 1761754199),
(51189, 'Joshua 18:10', 'Joshua', 18, 10, 'بیا یوشع د هغوی دپاره په شیلوه کې د څښتن په حضور کې پچه واچوله او د اسراییلو هرې پاتې قبیلې ته یې د ځمکې یوه ټاکلې برخه ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_10.mp3', '', 1761754199, 1761754199),
(51190, 'Joshua 18:11', 'Joshua', 18, 11, 'لومړنۍ قبیله چې د پچې له مخې یې ځمکه تر لاسه کړه هغه د بنیامین قبیله وه. د هغوی د طایفو ځمکه د یهودا او یوسف د قبیلو ترمنځ پرته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_11.mp3', '', 1761754199, 1761754199),
(51191, 'Joshua 18:12', 'Joshua', 18, 12, 'په شمال کې د هغوی سرحد د اردن د سیند څخه پیل شوی دی او بیا د اریحا په شمالي مخ ځوړي باندې پورته تللی او په لوېدیځ کې د غرنۍ سیمې په لاره بیت آون ته نژدې دښتې ته رسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_12.mp3', '', 1761754199, 1761754199),
(51192, 'Joshua 18:13', 'Joshua', 18, 13, 'بیا دا سرحد هغه مخ ځوړي ته چې د لوز (چې بیت ییل هم بلل کیږي) جنوب خواته دی تللی دی. بیا هغه عطاروت ادار ته چې د ښکتني بیت حورون په جنوب کې په غره باندې ؤ، رسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_13.mp3', '', 1761754199, 1761754199),
(51193, 'Joshua 18:14', 'Joshua', 18, 14, 'بیا دا سرحد بلې خواته تللی، د دې غره د لوېدیځې خوا څخه جنوب ته ګرځېدلی او قریت بعل (قریت یعاریم) ته وتلی دی. هغه ځای د یهودا د قبیلې دی. دا لوېدیځ سرحد ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_14.mp3', '', 1761754199, 1761754199),
(51194, 'Joshua 18:15', 'Joshua', 18, 15, 'جنوبي سرحد د قریت یعاریم د غاړې څخه شروع شوی او د نفتوح چینو ته رسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_15.mp3', '', 1761754199, 1761754199),
(51195, 'Joshua 18:16', 'Joshua', 18, 16, 'بیا دا سرحد د غره بېخ ته چې د هنوم د زوی درې ته مخامخ دی او د رفاییم د درې په شمال کې دی ښکته شوی دی. د هغه ځای څخه جنوب خواته د هنوم د درې له لارې هغې غونډۍ ته چې د اورشلیم په جنوب کې ده تللی او بیا عین روجل ته رسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_16.mp3', '', 1761754199, 1761754199),
(51196, 'Joshua 18:17', 'Joshua', 18, 17, 'بیا د شمال خواته عین شمس ته ګرځېدلی او بیا د جلیلوت خواته چې د ادومیم غاښي ته مخامخ ؤ، وتلی دی. دا سرحد بیا د بوهن ګټ ته ښکته شوی دی (بوهن د روبین زوی ؤ)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_17.mp3', '', 1761754199, 1761754199),
(51197, 'Joshua 18:18', 'Joshua', 18, 18, 'او د هغې غونډۍ شمال خواته تېر شوی چې د اردن دره ورڅخه ښکاري. بیا دا سرحد درې ته ښکته شوی دی،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_18.mp3', '', 1761754199, 1761754199),
(51198, 'Joshua 18:19', 'Joshua', 18, 19, 'د هغه ځای څخه د بیت حجلې د غونډۍ د شمالي خوا څخه تېر شوی او د مړې بحیرې په شمال کې چې د اردن سیند ورسره یوځای کیږي ختم شوی دی. دا جنوبي سرحد ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_19.mp3', '', 1761754199, 1761754199),
(51199, 'Joshua 18:20', 'Joshua', 18, 20, 'د اردن سیند ختیځ سرحد ؤ. دا د هغې خاورې سرحدونه وو چې د بنیامین د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_20.mp3', '', 1761754199, 1761754199),
(51200, 'Joshua 18:21', 'Joshua', 18, 21, 'د بنیامین د قبیلې د طایفو ښارګوټي دا وو: اریحا، بیت حجله، عمیق قصیص،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_21.mp3', '', 1761754199, 1761754199),
(51201, 'Joshua 18:22', 'Joshua', 18, 22, 'بیت عربه، صمارایم، بیت ییل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_22.mp3', '', 1761754199, 1761754199),
(51202, 'Joshua 18:23', 'Joshua', 18, 23, 'عویم، فاره، عفره،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_23.mp3', '', 1761754199, 1761754199),
(51203, 'Joshua 18:24', 'Joshua', 18, 24, 'کفرعموني، عفني او جابع د شاوخوا کلیو سره دولس ښارګوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_24.mp3', '', 1761754199, 1761754199),
(51204, 'Joshua 18:25', 'Joshua', 18, 25, 'جبعون، رامه، بیروت،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_25.mp3', '', 1761754199, 1761754199),
(51205, 'Joshua 18:26', 'Joshua', 18, 26, 'مصفه، کفیره، موزا،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_26.mp3', '', 1761754199, 1761754199),
(51206, 'Joshua 18:27', 'Joshua', 18, 27, 'راقم، یرفییل، تراله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_27.mp3', '', 1761754199, 1761754199),
(51207, 'Joshua 18:28', 'Joshua', 18, 28, 'صیله، الف، یبوسي ښار (اورشلیم)، جبعه او قریت یعاریم - د شاوخوا کلیو سره څوارلس ښارګوټي. دا هغه ځمکه وه چې د بنیامین د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua18_verse_28.mp3', '', 1761754199, 1761754199),
(51208, 'Psalms 133:1', 'Psalms', 133, 1, 'څومره ښه او په زړه پورې ده دا د خدای د قوم دپاره چې کله اوسیږي هغوی په اتفاق سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms133_verse_1.mp3', '', 1761754199, 1761754199),
(51209, 'Psalms 133:2', 'Psalms', 133, 2, 'دا د مسح کولو د قیمتي تېلو په شان دي چې راتوییږي د هارون په سر او ږیرې باندې او راتوییږي یې د چپن په غاړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms133_verse_2.mp3', '', 1761754199, 1761754199),
(51210, 'Psalms 133:3', 'Psalms', 133, 3, 'دا لکه پرخه چې پرته وي د حرمون په غره چې راوریږي د صهیون په غرونو دا هغه ځای دی چې څښتن ورکړ برکت د داسې ژوند چې ختمیږي نه هېڅکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms133_verse_3.mp3', '', 1761754199, 1761754199);